// Protótipo isolado: nenhuma chamada a APIs, sessão ou dados reais.
const notice=document.querySelector('#notice');let timer;
function notify(text){notice.textContent=text;notice.hidden=false;clearTimeout(timer);timer=setTimeout(()=>notice.hidden=true,5000)}
document.querySelectorAll('[data-preview]').forEach(el=>el.addEventListener('click',()=>notify(el.dataset.preview)));
const list=document.querySelector('#client-list');
if(list){const names=['Acácia','Aurora','Boreal','Brisa','Cais','Cedro','Cristal','Delta','Duna','Elo','Estrela','Farol','Flora','Horizonte','Íris','Jade','Lagoa','Lótus','Lume','Maré','Nascente','Norte','Oásis','Oliva','Orla','Paineira','Pérola','Pluma','Ponte','Prisma','Raiz','Riacho','Serra','Solar','Terra','Trilha','Vale','Vento','Vértice'];
function render(){const value=document.querySelector('#search').value.toLocaleLowerCase('pt-BR');const visible=names.filter(n=>n.toLocaleLowerCase('pt-BR').includes(value));list.replaceChildren();for(const name of visible){const a=document.createElement('a');a.className='client';a.href='#clientes';const avatar=document.createElement('span');avatar.className='avatar';avatar.textContent=name.slice(0,2).toUpperCase();const label=document.createElement('span');label.textContent='Cliente '+name;const arrow=document.createElement('span');arrow.style.marginLeft='auto';arrow.textContent='↗';a.append(avatar,label,arrow);a.addEventListener('click',e=>{e.preventDefault();notify('Prévia visual: a seleção abrirá a análise de Cliente '+name+' no sistema.');});list.append(a)}document.querySelector('#count').textContent=visible.length+' de 39 clientes';document.querySelector('#empty').hidden=visible.length!==0}
document.querySelector('#search').addEventListener('input',render);document.querySelector('#search').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();list.querySelector('a')?.click()}});document.querySelector('.tool[href="#clientes"]').addEventListener('click',()=>setTimeout(()=>document.querySelector('#search').focus(),20));render()}
const toggle=document.querySelector('#toggle-results');if(toggle){const results=document.querySelector('#results');function show(visible){results.hidden=!visible;toggle.setAttribute('aria-expanded',String(visible));toggle.textContent=visible?'Ver estado inicial':'Ver resultados de exemplo'}toggle.addEventListener('click',()=>show(results.hidden));document.querySelector('#zip').addEventListener('change',e=>{document.querySelector('#filename').textContent=e.target.files[0]?.name||'Nenhum arquivo selecionado'});document.querySelector('#analyze').addEventListener('click',()=>{show(true);notify('Prévia de resultados sintéticos. Nenhum arquivo foi enviado ou processado.');});document.querySelectorAll('.copy').forEach(button=>button.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(button.dataset.sql);notify('SQL sintético copiado.')}catch{notify('Cópia indisponível neste navegador. Utilize localhost para testar.')}}))}
